        car_rental_ids = [c.rental_id for c in self.car_rentals.values() if c.user_id == user_id]

        return {
            "user_id": user_id,
            "booking_ids": booking_ids,
            "hotel_ids": hotel_ids,
            "car_rental_ids": car_rental_ids,
        }

